#include <iostream>
#include <stack>
#include <string>

const std::string OPEN = "([{";
const std::string CLOSE = ")]}";

bool isValid(const std::string& line) {
    std::stack<char> stack;
    for (char ch : line) {
        if (OPEN.find(ch) != std::string::npos) {
            stack.push(ch);
        } else if (CLOSE.find(ch) != std::string::npos) {
            char open = OPEN[CLOSE.find(ch)];
            if (stack.empty() || stack.top() != open) {
                return false;
            }
            stack.pop();
        }
    }
    return stack.empty();
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    int n = std::stoi(line);
    for (int i = 0; i < n; i++) {
        std::getline(std::cin, line);
        std::cout << (isValid(line) ? "true" : "false") << "\n";
    }
    return 0;
}

