import { readFileSync } from "node:fs";

const lines = readFileSync(0, "utf8").split("\n");

const PAIRS = new Map([
  [")", "("],
  ["]", "["],
  ["}", "{"],
]);

function isValid(line: string): boolean {
  const stack: string[] = [];
  for (const ch of line) {
    const open = PAIRS.get(ch);
    if ("([{".includes(ch)) {
      stack.push(ch);
    } else if (open !== undefined) {
      if (stack.length === 0 || stack.at(-1) !== open) {
        return false;
      }
      stack.pop();
    }
  }
  return stack.length === 0;
}

const n = Number(lines[0]);
for (let i = 1; i <= n; i++) {
  console.log(isValid(lines[i] ?? "") ? "true" : "false");
}
